-- Online Judge schema: 21 tables + 2 rankings views (PostgreSQL 16)
CREATE EXTENSION IF NOT EXISTS citext;
CREATE TABLE users (id BIGSERIAL PRIMARY KEY, username VARCHAR(32) NOT NULL UNIQUE, email CITEXT NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, full_name VARCHAR(100), avatar_url TEXT, bio VARCHAR(500), school VARCHAR(150), role VARCHAR(12) NOT NULL DEFAULT 'USER' CHECK(role IN ('USER','SETTER','ADMIN')), status VARCHAR(12) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','LOCKED','BANNED')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE refresh_tokens (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash CHAR(64) NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,revoked_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE password_reset_tokens (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash CHAR(64) NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,used_at TIMESTAMPTZ);
CREATE TABLE achievements (id SERIAL PRIMARY KEY,code VARCHAR(50) UNIQUE NOT NULL,name VARCHAR(100) NOT NULL,description VARCHAR(255),icon_url TEXT);
CREATE TABLE user_achievements (user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,achievement_id INT REFERENCES achievements(id),earned_at TIMESTAMPTZ DEFAULT NOW(),PRIMARY KEY(user_id,achievement_id));
CREATE TABLE tags (id SERIAL PRIMARY KEY,name VARCHAR(50) NOT NULL UNIQUE,slug VARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE problems (id BIGSERIAL PRIMARY KEY,slug VARCHAR(100) NOT NULL UNIQUE,title VARCHAR(200) NOT NULL,statement TEXT NOT NULL,input_format TEXT,output_format TEXT,constraints_text TEXT,difficulty VARCHAR(10) NOT NULL CHECK(difficulty IN ('EASY','MEDIUM','HARD')),time_limit_ms INT NOT NULL DEFAULT 1000,memory_limit_mb INT NOT NULL DEFAULT 256,visibility VARCHAR(20) NOT NULL DEFAULT 'DRAFT' CHECK(visibility IN ('DRAFT','PUBLIC','CONTEST_ONLY','PENDING_REVIEW')),author_id BIGINT NOT NULL REFERENCES users(id),submission_count INT NOT NULL DEFAULT 0,accepted_count INT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),deleted_at TIMESTAMPTZ);
CREATE INDEX idx_problems_public ON problems(visibility,difficulty) WHERE deleted_at IS NULL;
CREATE TABLE problem_tags (problem_id BIGINT REFERENCES problems(id) ON DELETE CASCADE,tag_id INT REFERENCES tags(id) ON DELETE CASCADE,PRIMARY KEY(problem_id,tag_id));
CREATE TABLE test_cases (id BIGSERIAL PRIMARY KEY,problem_id BIGINT REFERENCES problems(id) ON DELETE CASCADE,input TEXT NOT NULL,expected_output TEXT NOT NULL,is_sample BOOLEAN NOT NULL DEFAULT FALSE,weight INT NOT NULL DEFAULT 1 CHECK(weight>0),order_index INT NOT NULL,UNIQUE(problem_id,order_index));
CREATE TABLE languages (id SERIAL PRIMARY KEY,code VARCHAR(20) NOT NULL UNIQUE,name VARCHAR(50) NOT NULL,judge0_id INT NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE contests (id BIGSERIAL PRIMARY KEY,slug VARCHAR(100) UNIQUE NOT NULL,title VARCHAR(200) NOT NULL,description TEXT,rule VARCHAR(8) NOT NULL DEFAULT 'ICPC' CHECK(rule IN ('ICPC','IOI')),status VARCHAR(16) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PUBLISHED','CANCELLED')),start_time TIMESTAMPTZ NOT NULL,end_time TIMESTAMPTZ NOT NULL,freeze_minutes INT NOT NULL DEFAULT 0,penalty_minutes INT NOT NULL DEFAULT 20,is_public BOOLEAN NOT NULL DEFAULT TRUE,access_code VARCHAR(50),created_by BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(end_time>start_time));
CREATE TABLE contest_problems (contest_id BIGINT REFERENCES contests(id) ON DELETE CASCADE,problem_id BIGINT REFERENCES problems(id),label VARCHAR(5) NOT NULL,points INT NOT NULL DEFAULT 100,order_index INT NOT NULL,PRIMARY KEY(contest_id,problem_id),UNIQUE(contest_id,label));
CREATE TABLE contest_registrations (contest_id BIGINT REFERENCES contests(id) ON DELETE CASCADE,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,registered_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),first_entered_at TIMESTAMPTZ,PRIMARY KEY(contest_id,user_id));
CREATE TABLE submissions (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),problem_id BIGINT NOT NULL REFERENCES problems(id),contest_id BIGINT REFERENCES contests(id),language_id INT NOT NULL REFERENCES languages(id),source_code TEXT NOT NULL CHECK(length(source_code)<=65536),verdict VARCHAR(12) NOT NULL DEFAULT 'PENDING',score NUMERIC(5,2) NOT NULL DEFAULT 0,passed_tests INT NOT NULL DEFAULT 0,total_tests INT NOT NULL DEFAULT 0,max_time_ms INT,max_memory_kb INT,compile_output TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),judged_at TIMESTAMPTZ);
CREATE INDEX idx_sub_pending ON submissions(created_at) WHERE verdict IN ('PENDING','JUDGING');
CREATE TABLE submission_test_results (id BIGSERIAL PRIMARY KEY,submission_id BIGINT REFERENCES submissions(id) ON DELETE CASCADE,test_case_id BIGINT REFERENCES test_cases(id) ON DELETE CASCADE,verdict VARCHAR(12) NOT NULL,time_ms INT,memory_kb INT,UNIQUE(submission_id,test_case_id));
CREATE TABLE user_problem_status (user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,problem_id BIGINT REFERENCES problems(id) ON DELETE CASCADE,is_solved BOOLEAN NOT NULL DEFAULT FALSE,attempts INT NOT NULL DEFAULT 0,first_solved_at TIMESTAMPTZ,PRIMARY KEY(user_id,problem_id));
CREATE TABLE contest_problem_results (contest_id BIGINT NOT NULL,user_id BIGINT NOT NULL,problem_id BIGINT NOT NULL,attempts INT NOT NULL DEFAULT 0,best_score NUMERIC(7,2) NOT NULL DEFAULT 0,is_solved BOOLEAN NOT NULL DEFAULT FALSE,solved_at TIMESTAMPTZ,last_submit_at TIMESTAMPTZ,PRIMARY KEY(contest_id,user_id,problem_id),FOREIGN KEY(contest_id,user_id) REFERENCES contest_registrations(contest_id,user_id) ON DELETE CASCADE,FOREIGN KEY(contest_id,problem_id) REFERENCES contest_problems(contest_id,problem_id) ON DELETE CASCADE);
CREATE TABLE tutorials (id BIGSERIAL PRIMARY KEY,problem_id BIGINT UNIQUE NOT NULL REFERENCES problems(id) ON DELETE CASCADE,author_id BIGINT REFERENCES users(id),content TEXT NOT NULL,is_published BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE comments (id BIGSERIAL PRIMARY KEY,problem_id BIGINT REFERENCES problems(id) ON DELETE CASCADE,user_id BIGINT REFERENCES users(id),parent_id BIGINT REFERENCES comments(id) ON DELETE CASCADE,content TEXT NOT NULL,vote_score INT NOT NULL DEFAULT 0,is_hidden BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW(),deleted_at TIMESTAMPTZ);
CREATE TABLE comment_votes (comment_id BIGINT REFERENCES comments(id) ON DELETE CASCADE,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,value SMALLINT NOT NULL CHECK(value IN (-1,1)),PRIMARY KEY(comment_id,user_id));
CREATE TABLE audit_logs (id BIGSERIAL PRIMARY KEY,actor_id BIGINT REFERENCES users(id),action VARCHAR(50) NOT NULL,target_type VARCHAR(30) NOT NULL,target_id BIGINT,detail JSONB,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE VIEW v_contest_standings AS WITH a AS (SELECT r.contest_id,r.user_id,c.rule,COUNT(*) FILTER (WHERE cr.is_solved) AS solved,COALESCE(SUM(cr.best_score),0) AS total_score,COALESCE(SUM(CASE WHEN cr.is_solved THEN FLOOR(EXTRACT(EPOCH FROM (cr.solved_at-c.start_time))/60)+cr.attempts*c.penalty_minutes ELSE 0 END),0)::INT AS penalty,MAX(cr.solved_at) AS last_ac_at FROM contest_registrations r JOIN contests c ON c.id=r.contest_id LEFT JOIN contest_problem_results cr ON cr.contest_id=r.contest_id AND cr.user_id=r.user_id GROUP BY r.contest_id,r.user_id,c.rule) SELECT a.*,u.username,RANK() OVER(PARTITION BY contest_id ORDER BY CASE WHEN rule='ICPC' THEN solved ELSE total_score END DESC,CASE WHEN rule='ICPC' THEN penalty END ASC,last_ac_at ASC NULLS LAST) AS rank FROM a JOIN users u ON u.id=a.user_id;
CREATE VIEW v_global_leaderboard AS WITH a AS (SELECT u.id AS user_id,u.username,u.avatar_url,COUNT(p.id) AS solved,COALESCE(SUM(CASE p.difficulty WHEN 'EASY' THEN 10 WHEN 'MEDIUM' THEN 20 WHEN 'HARD' THEN 40 ELSE 0 END),0) AS points,MAX(s.first_solved_at) AS last_solved_at FROM users u LEFT JOIN user_problem_status s ON s.user_id=u.id AND s.is_solved LEFT JOIN problems p ON p.id=s.problem_id WHERE u.status='ACTIVE' GROUP BY u.id) SELECT a.*,RANK() OVER(ORDER BY points DESC,solved DESC,last_solved_at ASC NULLS LAST) AS rank FROM a;
